func TestTheBitmapSetKeepsWhatKinMakes(emonT *testing.T) {
	var s *port.BitmapSet = port.NewBitmapSet()
	port.AssertEq(emonT, port.BmsHas(s, 5), 0, "empty")
	port.AssertEq(emonT, port.BitmapW(port.BmsGet(s, 5)), 0, "an absent bitmap is 0 x 0")
	port.AssertEq(emonT, port.BitmapH(port.BmsGet(s, 5)), 0, "in both directions")
	var b *port.Bitmap = port.BmsPut(s, plan.ViewBase(), 4, 3, 1)
	port.AssertEq(emonT, port.BmsHas(s, plan.ViewBase()), 1, "put")
	port.AssertEq(emonT, port.BitmapW(b), 4, "its width")
	port.AssertEq(emonT, port.BitmapH(b), 3, "its height")
	port.AssertEq(emonT, port.BitmapChannels(b), 1, "its channels")
	port.AssertEq(emonT, port.BitmapU8(b, 1, 1, 0), 0, "zeroed")
	port.BitmapSetU8(b, 1, 1, 0, 200)
	port.AssertEq(emonT, port.BitmapU8(port.BmsGet(s, plan.ViewBase()), 1, 1, 0), 200, "the set holds the very bitmap kin filled")
	port.AssertEq(emonT, port.BmsHas(s, plan.ViewBase()+1), 0, "another id is absent")
}
